import{z as A,x as l,o as t,c as d,q as s,j as B,D as e,d as i,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"扰动法与高阶","description":"","frontmatter":{"title":"扰动法与高阶","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/perturbation-methods.md","filePath":"econ/perturbation-methods.md","lastUpdated":1791413859000}'),p={name:"econ/perturbation-methods.md"};function m(u,a,h,D,g,F){const r=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="扰动法与高阶" tabindex="-1">扰动法与高阶 <a class="header-anchor" href="#扰动法与高阶" aria-label="Permalink to &quot;扰动法与高阶&quot;">​</a></h1><div class="epigraph"><p>把冲击尺度当成扰动参数，政策函数在确定性稳态邻域按阶展开；一阶是确定性等价，二阶才见风险。</p><footer>—— Judd, Perturbation methods；Schmitt-Grohé and Uribe, Solving Dynamic General Equilibrium Models Using a Second-Order Approximation, JEDC 2004</footer></div><p><a href="/econ/blanchard-kahn">上一课</a>给出一阶唯一解。对数线性在一阶关掉了方差。本课缺口是：<strong>升阶</strong>。二阶扰动让风险溢价、确定性等价失效、福利的二阶项重新出现。不重数 BK 的根。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>令冲击为 \\(\\sigma\\varepsilon_t\\)，政策 \\(g(s,\\sigma)\\)。\\(\\sigma=0\\) 时退回确定性稳态。对 \\(\\sigma\\) 与状态偏导，逐阶解线性方程：一阶系数即 BK 的决策规则；二阶出现 \\(\\sigma^2\\) 项与状态的二次型。Schmitt-Grohé–Uribe：二阶近似下，均值会离开确定性稳态（常数项修正），资产回报出现协方差项。缺口不是再线性化一次，而是声明一阶 IRF 不能回答的问题要用二阶及以上。</p><p><span class="marginnote">三阶才让风险溢价随状态变（时变溢价）。Fernández-Villaverde 与 Rubio-Ramírez 把扰动接到似然。本课只钉阶的经济学，不写张量代数。</span></p><p><span class="marginnote">术语翻译：扰动法就是把冲击的大小 \\(\\sigma\\) 当成一个旋钮。\\(\\sigma=0\\) 时世界完全可预测，模型退化成一条确定性路径；然后问：把旋钮从 0 慢慢拧大一点点，最优决策规则怎么变？答案按 \\(\\sigma\\) 的幂次一项一项解出来——一阶项、二阶项，本质上是对 \\(\\sigma\\) 做泰勒展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>隐函数定理在 \\(F(g,g&#39;,\\sigma)=0\\) 上对参数求导。计算上：一阶用 QZ；二阶把已知一阶系数代入二次恒等式。修剪（pruning）避免高阶项的爆炸伪周期。福利：Lucas 的消费波动成本是二阶，必须在二阶政策（或确定性等价加二阶效用）上算；用一阶消费波动配二阶效用要声明。</p>',9)),(t(),B(o,null,{default:e(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%CF%83%3D0%20%E7%A8%B3%E6%80%81%22%5D%20--%3E%20FO%5B%22%E4%B8%80%E9%98%B6%3A%20BK%20%2F%20%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%AD%89%E4%BB%B7%22%5D%0A%20%20FO%20--%3E%20SO%5B%22%E4%BA%8C%E9%98%B6%3A%20%E5%9D%87%E5%80%BC%E4%BF%AE%E6%AD%A3%E4%B8%8E%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20SO%20--%3E%20HO%5B%22%E4%B8%89%E9%98%B6%3A%20%E6%97%B6%E5%8F%98%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 VFI 对照：扰动快、适合高维平滑模型；在约束绑定、ZLB、离散选择处失败，因为政策不可微。那些点用投影或 OccBin 一类分段线性。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是泰勒在 \\(\\sigma\\) 方向。风险以方差的形式从二阶进入决策：预防性储蓄、债券溢价、开放经济的风险分享缺口，都是 \\(\\sigma^2\\) 量级。IRF 在二阶对冲击符号不再对称：大衰退与大繁荣的线性镜像被打破。确定性等价的宏观含义：若只关心一阶矩的脉冲，许多模型用一阶就够；若关心资产价格或福利排序，不够。",-1)),a[6]||(a[6]=E("p",null,"什么问题需要升阶、什么问题不必，按提问来分流：",-1)),(t(),B(o,null,{default:e(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BD%A0%E8%A6%81%E5%9B%9E%E7%AD%94%E4%BB%80%E4%B9%88%E9%97%AE%E9%A2%98%EF%BC%9F%22%5D%20--%3E%20M%5B%22%E5%8F%AA%E7%9C%8B%E5%9D%87%E5%80%BC%20IRF%22%5D%0A%20%20Q%20--%3E%20W%5B%22%E7%A6%8F%E5%88%A9%E6%8E%92%E5%BA%8F%E6%88%96%E8%B5%84%E4%BA%A7%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20M%20--%3E%20F1%5B%22%E4%B8%80%E9%98%B6%E8%BF%91%E4%BC%BC%E5%B0%B1%E5%A4%9F%EF%BC%9A%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%AD%89%E4%BB%B7%22%5D%0A%20%20W%20--%3E%20F2%5B%22%E5%BF%85%E9%A1%BB%E5%8D%87%E5%88%B0%E4%BA%8C%E9%98%B6%EF%BC%9A%CF%83%C2%B2%20%E9%A1%B9%E8%BF%9B%E5%85%A5%E5%86%B3%E7%AD%96%22%5D%0A%20%20F2%20--%3E%20A%5B%22%E9%A2%84%E9%98%B2%E6%80%A7%E5%82%A8%E8%93%84%E5%87%BA%E7%8E%B0%22%5D%0A%20%20F2%20--%3E%20B%5B%22%E5%80%BA%E5%88%B8%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E5%87%BA%E7%8E%B0%22%5D%0A%20%20F2%20--%3E%20C%5B%22IRF%20%E5%AF%B9%E6%AD%A3%E8%B4%9F%E5%86%B2%E5%87%BB%E4%B8%8D%E5%86%8D%E5%AF%B9%E7%A7%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：升到二阶不是为了把答案多算几位小数，而是有些经济学量（风险溢价、预防性储蓄、福利成本）在一阶上恰好等于零——一阶算得再准，答案也还是 0。升阶是把被线性化抹掉的非零二阶项找回来，属于「有没有」的问题，不是「准不准」的问题。</span></p><p><span class="marginnote">数字实例：预防性储蓄与溢价这类项大致是 \\(\\sigma^2\\) 量级。取年消费波动 \\(\\sigma=2\\%\\)，则 \\(\\sigma^2=0.0004\\)；再乘上系数 5（如相对风险厌恶），得到约 \\(0.2\\%\\) 的量级——小，但对资产定价和福利比较是头等大事，而线性化把它们全看成了零。</span></p><p>Smets–Wouters 类估计多数仍在一阶线性高斯，似然好写。把扰动升阶再估计，是后课贝叶斯的延伸，不是默认。</p><p><span class="marginnote">Judd 的扰动与投影是两条数值路线：一个在一点展开，一个在区间上加权残差。下一课投影。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把高阶写成交易策略，不估计期权。全局多重均衡、大灾害（disaster）使展开点本身可疑。异质主体加分布状态时，扰动要对测度做函数泰勒，技术上可行但本课不展开——HANK 常用序列空间或投影，不默认三阶 DSGE。</p><p>后课默认：一阶 = 确定性等价 IRF；二阶及以上才谈风险修正。下一课：当局部展开不够时，用基函数在全域配平残差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扰动按冲击尺度升阶；一阶 BK，二阶见风险与均值修正。</li><li>约束与不可微政策打断扰动。</li><li>福利比较至少二阶。</li><li>出处：Judd；Schmitt-Grohé and Uribe, <em>JEDC</em> 2004。</li></ul>',9))])}const f=A(p,[["render",m]]);export{b as __pageData,f as default};
